<?php $items=$pdo->query("SELECT title,due_date,priority,status FROM tasks WHERE due_date IS NOT NULL ORDER BY due_date LIMIT 50")->fetchAll(); ?>
<div class="page-head"><div><span class="eyebrow">ORGANIZAÇÃO</span><h1>Agenda</h1><p>Compromissos e prazos centralizados.</p></div><a class="btn primary" href="?module=tarefas">+ Criar tarefa</a></div><div class="panel"><div class="timeline"><?php foreach($items as $i):?><div class="timeline-item"><div class="date-box"><b><?=date('d',strtotime($i['due_date']))?></b><span><?=strtoupper(date('M',strtotime($i['due_date'])))?></span></div><div><h3><?=e($i['title'])?></h3><p><?=date('d/m/Y H:i',strtotime($i['due_date']))?> • <?=e($i['priority'])?></p></div><span class="badge <?=badgeClass($i['status'])?>"><?=e($i['status'])?></span></div><?php endforeach;?><?php if(!$items):?><p class="empty">Nenhum compromisso agendado.</p><?php endif;?></div></div>
